from pydantic import BaseModel, Field

class PaperCitationRecord(BaseModel):
    """One provided paper: its title and the titles of other provided papers it references."""
    paper_title: str | None = Field(description="The title of the paper currently being parsed")
    references_other_provided_papers: list[str] = Field(
        description="Titles of the OTHER provided papers that appear in this paper's bibliography"
    )

class Parse(BaseModel):
    papers: list[PaperCitationRecord]
